using System;
using System.Collections.Generic;
using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DualityDegreeOmenData", menuName = "Data/Battle/Omens System/Omen Data/Moonie/DualityDegreeOmenData")]
public class DualityDegreeOmenData : ConvertOmenData
{
	[NonSerialized]
	private OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Add(omenInstance);
		this.omenInstance = omenInstance;
	}

	protected override Action<List<DiceInstance>> InitializeOmenAction(OmenInstance omenInstance)
	{
		return delegate(List<DiceInstance> diceInstances)
		{
			if (!AlreadyUsed)
			{
				int diceConvertedAmount = diceInstances.Count;
				InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 10, delegate
				{
					for (int i = 0; i < diceConvertedAmount; i++)
					{
						ActivateOmen();
						if (counter == 0)
						{
							ToggleAlreadyUsed(toggle: true);
							omenInstance.ToggleOmenCounter(toggle: false);
							omenInstance.EnqueueOmenFeedbackAndPlay();
							break;
						}
					}
					if (!AlreadyUsed)
					{
						omenInstance.UpdateOmenCounter();
					}
				});
			}
		};
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Remove(omenInstance);
	}
}
